<script setup>
import {computed} from 'vue';
defineOptions({inheritAttrs:false});
const props=defineProps({modelValue:{type:Number,required:true},min:{type:Number,default:0},max:{type:Number,default:100},step:{type:Number,default:1},unit:{type:String,default:''},displayValue:{type:String,default:undefined}});
const emit=defineEmits(['update:modelValue']);
const percentage=computed(()=>Math.max(0,Math.min(100,(props.modelValue-props.min)/(props.max-props.min)*100)));
</script>
<template><div class="range-control"><input v-bind="$attrs" type="range" :value="modelValue" :min="min" :max="max" :step="step" :style="{'--range-fill':`${percentage}%`}" :aria-valuetext="displayValue??`${modelValue}${unit}`" @input="emit('update:modelValue',Number($event.target.value))"/><output aria-hidden="true">{{displayValue??`${modelValue}${unit}`}}</output></div></template>
<style scoped>
.range-control{display:flex;align-items:center;gap:12px;min-width:0}.range-control output{min-width:3.7em;text-align:right;font-variant-numeric:tabular-nums;color:var(--accent);font-size:.82rem}.range-control input{appearance:none;-webkit-appearance:none;width:100%;height:32px;padding:0;border:0;box-shadow:none;background:transparent;cursor:pointer}.range-control input::-webkit-slider-runnable-track{height:6px;border-radius:8px;background:linear-gradient(to right,var(--accent) var(--range-fill),var(--line) var(--range-fill))}.range-control input::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:20px;height:20px;margin-top:-7px;border:3px solid var(--surface);border-radius:50%;background:var(--accent);box-shadow:0 0 0 1px var(--accent),0 2px 5px #30272d20;transition:box-shadow .15s}.range-control input:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:4px}.range-control input::-moz-range-track{height:6px;border-radius:8px;background:var(--line)}.range-control input::-moz-range-progress{height:6px;background:var(--accent)}.range-control input::-moz-range-thumb{width:16px;height:16px;border:3px solid var(--surface);border-radius:50%;background:var(--accent)}.range-control input:disabled{opacity:.5;cursor:default}@media(prefers-reduced-motion:reduce){.range-control input::-webkit-slider-thumb{transition:none}}
</style>
